mapper.select:
select qst_id as qstId,qst_name as qstName,qst_code as qstCode,qst_parent_id as qstParentId
from qs_type
where qst_state=1 and qst_parent_id =#{params.qstId}

select qst_id as qstId,qst_name as qstName,qst_code as qstCode,qst_parent_id as qstParentId
from qs_type
where qst_state=1 and qst_parent_id=#{qstParentId}

select * from qs_type

    
        and qst_name like concat('%',#{params.qstName},'%')
    
    
        and qst_code like concat('%',#{params.qstCode},'%')
    
    
        and qst_parent_id=#{params.qstParentId}
    
    
        and Qst_Is_Important=#{params.qstIsImportant}
    
    
        and severity_level=#{params.severityLevel}
    
    
        and Qst_Category=#{params.qstCategory}
    
    
        and Qst_Create_Uname like concat('%',#{params.qstCreateUname},'%')
    
    
        and Qst_State = #{params.qstState}
    

order by Qst_Sort

select con.Con_Name as conName,
f.file_relation_id as fileRelationId, c1.C_Name as qsrCname, c2.C_Name as qsrFzCname, u1.U_Name as qsrXdUname, mn.*,qt.* from Qs_Record mn left join Qs_Type qt on qt.Qst_Id=mn.Qst_Id left join Qs_Plan_Task qpt on qpt.id = mn.Pt_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Sys_Company c1 on c1.C_Id=mn.Qsr_Cid left join Sys_Company c2 on c2.C_Id=mn.Qsr_Fz_Cid left join Sys_User u1 on u1.U_Id=mn.Qsr_Xd_Uid left join Sys_File f on f.FileID=mn.Qsr_Id
qpt.State!=3
and mn.Qsr_Time >= #{params.startTime}
and mn.Qsr_Time <= #{params.endTime}
and qpt.Pt_Type=#{params.ptType}

update.foreach:
update qs_type
   
       
           qst_punish=#{item.qstPunish},
       
       
           qst_score=#{item.qstScore},
       
       
           qst_path=#{item.qstPath}
       
   
where qst_id=#{item.qstId}
